Method.Implementation:
Set tStatus = $$$OK
Try {
	If '$IsObject($get(pBatch)) Set tStatus = $$$ERROR($$$ObjectInstanceRequired) Quit
	If '$IsObject(pIOStream) {
		Set tFilename = pIOStream
		Set pIOStream = ##class(%IO.FileStream).%New()
		Do pIOStream.Open(tFilename,"WAE",,"UTF-8",.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.ARPacket) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.ARPacket).PutObject(pIOStream,pBatch.ARPacket,0)
		If $$$ISERR(tStatus) Quit
	}
	Set seqKey = ""
	For {
		Set tElement = pBatch.CPTPacket.GetNext(.seqKey)
		If (seqKey = "") Quit
		If $IsObject(tElement) {
			Set tStatus = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.CPTPacket).PutObject(pIOStream,tElement,0)
			If $$$ISERR(tStatus) Quit
		}
		Set tStatus = pBatch.CPTPacket.%UnSwizzleAt(seqKey)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Quit
	If $IsObject(pBatch.CasemixPacket1) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.CMIXPacket).PutObject(pIOStream,pBatch.CasemixPacket1,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.CasemixPacket2) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.CMIXPacket).PutObject(pIOStream,pBatch.CasemixPacket2,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.ProcedurePacket) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.ProcedurePacket).PutObject(pIOStream,pBatch.ProcedurePacket,0)
		If $$$ISERR(tStatus) Quit
	}
	If $IsObject(pBatch.EACPacket) {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.EACPacket).PutObject(pIOStream,pBatch.EACPacket,0)
		If $$$ISERR(tStatus) Quit
	}
	Do pIOStream.Flush(.tStatus)
	If $$$ISERR(tStatus) Quit
} Catch ex {
	Set tStatus = $$$SystemError
}
Quit tStatus

Set tStatus = $$$OK
Try {
	If '$IsObject(pIOStream) {
		Set tFilename = pIOStream
		Set pIOStream = ##class(%IO.FileStream).%New()
		Do pIOStream.Open(tFilename,,pTimeout,"UTF-8",.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	Set pIOStream.CharEncoding = "UTF-8"
	Set pBatch = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.Batch).%New()
	Set pBatch.%Source = pIOStream.Name
	Set pLookAhead = $get(pLookAhead)
	If (12 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(12-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If ($extract(pLookAhead,1,12) = "000000CODACT") {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.ARPacket).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"ARPacket","IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.ARPacket",$classname()),tStatus) Quit
		Set pBatch.ARPacket = tObject
	}
	If (12 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(12-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	Set tCount = 0
	While ($extract(pLookAhead,1,12) = "000000CODCPT") {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.CPTPacket).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		Set tCount = tCount + 1
		If $$$ISERR(tStatus) Quit
		If (999 < tCount) {
			Set tStatus = $$$ERROR($$$EnsRecordMapErrRepeatMax,999,"CPTPacket")
			Quit
		}
		Set tStatus = pBatch.CPTPacket.SetAt(tObject,tCount)
		If $$$ISERR(tStatus) Quit
		Set pLookAhead = pLookAhead _ pIOStream.Read(12-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexRepeating,"CPTPacket","IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.CPTPacket",$classname(),tCount),tStatus) Quit
	If (1 > tCount) {
		Set tStatus = $$$ERROR($$$EnsRecordMapErrRepeatMin,1,"CPTPacket")
		Quit
	}
	If (12 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(12-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If ($extract(pLookAhead,1,12) = "000000CODCOD") {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.CMIXPacket).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"CasemixPacket1","IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.CMIXPacket",$classname()),tStatus) Quit
		Set pBatch.CasemixPacket1 = tObject
	}
	If (12 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(12-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If ($extract(pLookAhead,1,12) = "000000CODCOD") {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.CMIXPacket).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"CasemixPacket2","IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.CMIXPacket",$classname()),tStatus) Quit
		Set pBatch.CasemixPacket2 = tObject
	}
	If (12 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(12-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If ($extract(pLookAhead,1,12) = "000000CODPDT") {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.ProcedurePacket).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"ProcedurePacket","IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.ProcedurePacket",$classname()),tStatus) Quit
		Set pBatch.ProcedurePacket = tObject
	}
	If (12 > $length(pLookAhead)) {
		Set pLookAhead = pLookAhead _ pIOStream.Read(12-$length(pLookAhead),pTimeout,.tStatus)
		If $$$ISERR(tStatus) Quit
	}
	If ($extract(pLookAhead,1,12) = "000000CODEAC") {
		Set tStatus = ##class(IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.EACPacket).GetObject(pIOStream,.tObject,pTimeout,.pLookAhead)
		If $$$ISERR(tStatus) Set tStatus = $system.Status.AppendStatus($$$ERROR($$$EnsRecordMapErrComplexBasic,"EACPacket","IHC.ITF.DStruc.Record.HdmAdtToiSeriesFixedBilling.EACPacket",$classname()),tStatus) Quit
		Set pBatch.EACPacket = tObject
	}
} Catch {
	Set tStatus = $$$SystemError
}
Quit tStatus
